pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // 1. Set up a concrete scenario: deploy a mock booster that returns shutdown=true
        // We'll use a minimal contract that implements ICVXBooster
        // For simplicity, we deploy a helper that returns shutdown
        // Actually, we can just use the fact that the booster address is zero (0) and the call will revert differently.
        // But the test requires the reference to succeed (no revert) and the second version to revert.
        // With booster = address(0), calling booster.poolInfo will revert in both versions before the divergence.
        // So we need a booster that returns shutdown = true.
        // We'll deploy a minimal booster mock inline.

        // Deploy a mock booster that returns shutdown = true for any pool
        BoosterMock mockBooster = new BoosterMock();
        // Redeploy C with mockBooster
        c = new C(address(this), address(0), BoosterMock(address(mockBooster)), new address[](0));
        // Set cvxPoolInfo so that poolInfo lookup returns the expected shutdown value
        // Since mockBooster returns shutdown = true for any pid, we don't need to set specific pid
        // However, isCvxShutdown reads cvxPoolInfo.pId, which defaults to 0, so it will call poolInfo(0) and get shutdown=true
        // The reference depositAndStake checks !isCvxShutdown() and does nothing (no revert).
        // The second version checks !isCvxShutdown() and else { revert(); } so it reverts.
        // We must catch the revert in the second version using try/catch.

        bool ok;
        try c.depositAndStake(100) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

interface ICVXBooster {
    struct PoolInfo {
        address lptoken;
        address token;
        address gauge;
        address crvRewards;
        address stash;
        bool shutdown;
    }
    function poolInfo(uint256 _pid) external view returns (PoolInfo memory);
}

contract BoosterMock {
    function poolInfo(uint256) external view returns (ICVXBooster.PoolInfo memory) {
        return ICVXBooster.PoolInfo({
            lptoken: address(0),
            token: address(0),
            gauge: address(0),
            crvRewards: address(0),
            stash: address(0),
            shutdown: true
        });
    }
}

